PANEL_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Hermes Smart Router v__VERSION__ Control Plane</title>
<style>
:root{--bg:#071018;--card:#0e1b27;--card2:#112435;--text:#e8f1f7;--muted:#91a7b8;--line:#20384a;--good:#64d2a2;--warn:#f5c66a;--bad:#ff7b83;--accent:#78b7ff;--purple:#bca7ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#112a3c 0,#071018 42%);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.layout{display:grid;grid-template-columns:245px 1fr;min-height:100vh}.side{border-right:1px solid var(--line);padding:22px 14px;position:sticky;top:0;height:100vh;background:#071018dd;backdrop-filter:blur(14px)}.brand{font-weight:800;font-size:18px;padding:8px 10px 20px}.brand small{display:block;color:var(--muted);font-weight:600;margin-top:4px}.nav button{width:100%;text-align:left;border:0;background:transparent;color:var(--muted);padding:10px 12px;border-radius:9px;cursor:pointer;margin:2px 0}.nav button.active,.nav button:hover{background:var(--card2);color:var(--text)}main{padding:24px 28px 70px;max-width:1500px}.top{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-bottom:20px}.top h1{font-size:24px;margin:0}.status{display:flex;gap:8px;align-items:center;color:var(--muted)}.dot{width:9px;height:9px;border-radius:50%;background:var(--warn)}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.card{background:linear-gradient(180deg,#102332,#0d1b27);border:1px solid var(--line);border-radius:13px;padding:15px;box-shadow:0 12px 40px #0002}.metric .value{font-size:28px;font-weight:800;margin-top:8px}.muted{color:var(--muted)}.section{margin-top:16px}.section h2{font-size:17px;margin:0 0 10px}.split{display:grid;grid-template-columns:1fr 1fr;gap:13px}.bars{display:grid;gap:9px}.barline{display:grid;grid-template-columns:100px 1fr 48px;gap:10px;align-items:center}.bar{height:9px;background:#0a151f;border-radius:9px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),var(--purple));border-radius:9px}.tablewrap{overflow:auto;max-height:480px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-weight:700;position:sticky;top:0;background:#0e1b27}.badge{display:inline-block;padding:3px 7px;border-radius:999px;background:#173047;color:#bcdcff;font-size:11px}.good{color:var(--good)}.bad{color:var(--bad)}.warn{color:var(--warn)}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.btn{border:1px solid #31516a;background:#173047;color:#e8f1f7;padding:8px 11px;border-radius:8px;cursor:pointer}.btn.primary{background:#1e69a5}.btn.danger{background:#6a2932}.btn:hover{filter:brightness(1.15)}input,select,textarea{background:#08141e;color:var(--text);border:1px solid #31516a;border-radius:8px;padding:8px;width:100%}textarea{min-height:100px}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.formgrid .wide{grid-column:1/-1}.modal{position:fixed;inset:0;background:#000a;display:none;place-items:center;z-index:10}.modal.open{display:grid}.dialog{width:min(700px,92vw);max-height:90vh;overflow:auto;background:#0d1b27;border:1px solid #31516a;border-radius:14px;padding:18px}.dialog h3{margin-top:0}.login{position:fixed;inset:0;background:#071018;z-index:20;display:grid;place-items:center}.loginbox{width:min(440px,92vw)}.loginbox h1{margin-top:0}.tabs{display:flex;gap:6px;margin-bottom:12px}.tabs button{flex:1}.hidden{display:none!important}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;white-space:pre-wrap;word-break:break-word;background:#071018;padding:10px;border-radius:8px;border:1px solid var(--line)}.pill{font-size:12px;padding:5px 8px;border:1px solid var(--line);border-radius:999px}.toast{position:fixed;right:22px;bottom:22px;background:#173047;border:1px solid #31516a;padding:11px 14px;border-radius:9px;display:none;z-index:30}.routegrid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.route{padding:14px;border:1px solid var(--line);border-radius:12px;background:#0b1823}.route h3{margin:0 0 8px;text-transform:uppercase;font-size:13px}.route .model{word-break:break-all;color:#c9def0;font-size:12px;min-height:34px}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,1fr)}.split,.routegrid{grid-template-columns:1fr}.layout{grid-template-columns:1fr}.side{position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}.nav{display:flex;overflow:auto}.nav button{min-width:max-content}main{padding:18px}}
</style></head><body>
<div id="login" class="login"><div class="card loginbox"><h1>Hermes Control Plane</h1><p class="muted">Smart Router v__VERSION__ · use a panel user or admin/API key.</p><div class="tabs"><button class="btn primary" onclick="loginMode('user')">User login</button><button class="btn" onclick="loginMode('key')">API key</button></div><div id="userLogin"><input id="username" placeholder="Username" value="admin"><br><br><input id="password" type="password" placeholder="Password"><br><br><button class="btn primary" onclick="doLogin()">Sign in</button></div><div id="keyLogin" class="hidden"><input id="apiKey" type="password" placeholder="SMART_ROUTER_ADMIN_API_KEY or srk_..."><br><br><button class="btn primary" onclick="useKey()">Use key</button></div><p id="loginErr" class="bad"></p></div></div>
<div class="layout"><aside class="side"><div class="brand">Hermes Router<small>Control Plane v__VERSION__</small></div><div class="nav" id="nav"></div></aside><main><div class="top"><div><h1 id="title">Overview</h1><div class="muted" id="subtitle">Routing, cost, security and agent operations</div></div><div class="status"><span class="dot" id="dot"></span><span id="who">not connected</span><button class="btn" onclick="logout()">Logout</button></div></div><div id="page"></div></main></div>
<div id="modal" class="modal"><div class="dialog"><div style="display:flex;justify-content:space-between;align-items:center"><h3 id="modalTitle">Edit</h3><button class="btn" onclick="closeModal()">Close</button></div><div id="modalBody"></div></div></div><div id="toast" class="toast"></div>
<script>
const pages=['Overview','Routing','Providers','Budgets','Users & Keys','Policies','Knowledge','Memory','Agents','Teams','Plugins','Audit','System'];let token=localStorage.getItem('hermes_v51_token')||'';let me=null;
const $=s=>document.querySelector(s); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(m){const t=$('#toast');t.textContent=m;t.style.display='block';setTimeout(()=>t.style.display='none',2800)}
async function api(path,opt={}){opt.headers={...(opt.headers||{}),'Authorization':'Bearer '+token};if(opt.body&&!opt.headers['Content-Type'])opt.headers['Content-Type']='application/json';const r=await fetch('api/'+path,opt);let d=null;try{d=await r.json()}catch{}if(r.status===401){showLogin();throw new Error('authentication required')}if(!r.ok)throw new Error(d?.error?.message||('HTTP '+r.status));return d}
function loginMode(m){$('#userLogin').classList.toggle('hidden',m!=='user');$('#keyLogin').classList.toggle('hidden',m!=='key')}
async function doLogin(){try{const r=await fetch('api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#username').value,password:$('#password').value})});const d=await r.json();if(!r.ok)throw new Error(d?.error?.message||'login failed');token=d.token;localStorage.setItem('hermes_v51_token',token);await boot()}catch(e){$('#loginErr').textContent=e.message}}
async function useKey(){token=$('#apiKey').value.trim();localStorage.setItem('hermes_v51_token',token);try{await boot()}catch(e){$('#loginErr').textContent=e.message}}
function showLogin(){$('#login').style.display='grid'}function logout(){token='';localStorage.removeItem('hermes_v51_token');showLogin()}
async function boot(){me=await api('me');$('#login').style.display='none';$('#who').textContent=me.actor+' · '+me.role;$('#dot').style.background='#64d2a2';renderNav();show('Overview')}
function renderNav(){const n=$('#nav');n.innerHTML=pages.map(p=>`<button data-p="${p}" onclick="show('${p}')">${p}</button>`).join('')}
async function show(p){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.p===p));$('#title').textContent=p;$('#page').innerHTML='<div class="card muted">Loading…</div>';try{const fn=window['page'+p.replace(/[^A-Za-z]/g,'')];await fn()}catch(e){$('#page').innerHTML=`<div class="card bad">${esc(e.message)}</div>`}}
function cards(items){return `<div class="grid">${items.map(([k,v,s])=>`<div class="card metric"><div class="muted">${k}</div><div class="value">${v}</div><div class="muted">${s||''}</div></div>`).join('')}</div>`}
function bars(obj){const e=Object.entries(obj||{});const max=Math.max(1,...e.map(x=>x[1]));return `<div class="bars">${e.map(([k,v])=>`<div class="barline"><span>${esc(k)}</span><div class="bar"><i style="width:${v/max*100}%"></i></div><b>${v}</b></div>`).join('')||'<span class="muted">No data yet</span>'}</div>`}
function table(rows,cols){return `<div class="tablewrap"><table><thead><tr>${cols.map(c=>`<th>${c[0]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c[2]?c[2](r[c[1]],r):esc(r[c[1]])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
async function pageOverview(){const d=await api('summary?hours=24');$('#page').innerHTML=cards([['Requests',d.requests,'24h'],['Cost','$'+Number(d.cost_usd).toFixed(4),'measured usage'],['Avg latency',d.avg_latency_ms+' ms','router → upstream'],['Error rate',d.error_rate+'%','HTTP ≥400']])+`<div class="split section"><div class="card"><h2>Tier distribution</h2>${bars(d.tiers)}</div><div class="card"><h2>Profiles</h2>${bars(d.profiles)}</div></div><div class="grid section">${[['Users',d.users],['API keys',d.api_keys],['Knowledge bases',d.knowledge_bases],['Agents',d.agents]].map(x=>`<div class="card"><div class="muted">${x[0]}</div><div class="value" style="font-size:24px;font-weight:800">${x[1]}</div></div>`).join('')}</div><div class="card section"><h2>Recent routes</h2>${table(d.recent,[['Time','ts'],['Actor','actor'],['Tier','tier'],['Profile','profile'],['Model','model'],['Status','status_code'],['Latency','latency_ms',(v)=>Number(v).toFixed(0)+' ms'],['Cost','cost_usd',(v)=>'$'+Number(v).toFixed(5)]])}</div>`}
async function pageRouting(){const r=await api('routes');$('#page').innerHTML=`<div class="toolbar"><button class="btn primary" onclick="discoverAndMap()">Discover upstream models</button></div><div class="routegrid">${r.map(x=>`<div class="route"><h3>${esc(x.name)}</h3><div class="model">${esc(x.model)}</div><p class="muted">min tier: ${esc(x.min_tier)} · max out ${x.max_output}</p><button class="btn" onclick='editRoute(${JSON.stringify(x)})'>Edit mapping</button></div>`).join('')}</div><div class="card section"><h2>How v0.5.1 routing works</h2><div class="code">Capability tier (fast/standard/strong) → specialized profile (coding/vision when detected) → mapped upstream model/route → provider gateway fallback.</div></div>`}
function editRoute(x){modal('Edit route '+x.name,`<div class="formgrid"><label>Model/route ID<input id="rmodel" value="${esc(x.model)}"></label><label>Max output<input id="rmax" type="number" value="${x.max_output}"></label><label class="wide">Description<input id="rdesc" value="${esc(x.description||'')}"></label><div class="wide"><button class="btn primary" onclick="saveRoute('${x.name}')">Save</button></div></div>`)}
async function saveRoute(name){await api('routes',{method:'PUT',body:JSON.stringify({name,model:$('#rmodel').value,max_output:+$('#rmax').value,description:$('#rdesc').value,enabled:true})});closeModal();toast('Route saved');show('Routing')}
async function discoverAndMap(){const d=await api('providers/discover');modal('Discovered upstream models',`<p>Health: <b class="${d.health?'good':'bad'}">${d.health?'healthy':'unhealthy'}</b> · ${d.latency_ms||0} ms</p><div class="code">${esc((d.models||[]).join('\n')||d.error||'No models returned')}</div>`)}
async function pageProviders(){const d=await api('providers/discover');$('#page').innerHTML=cards([['Health',d.health?'UP':'DOWN',d.upstream||''],['Discovery latency',(d.latency_ms||0)+' ms','live probe'],['Models',(d.models||[]).length,'returned by /v1/models'],['Gateway','Connected','dynamic profile mapping']])+`<div class="card section"><h2>Available models/routes</h2><div class="code">${esc((d.models||[]).join('\n')||d.error||'No models returned')}</div></div>`}
async function pageBudgets(){const d=await api('budgets');$('#page').innerHTML=`<div class="toolbar"><button class="btn primary" onclick="newBudget()">Add budget</button></div><div class="card">${table(d,[['ID','id'],['Scope','scope_type'],['Value','scope_value'],['Monthly USD','monthly_usd'],['Hard stop %','hard_stop_percent'],['Action','action'],['','id',(v)=>`<button class="btn danger" onclick="del('budgets/${v}','Budgets')">Delete</button>`]])}</div>`}
function newBudget(){modal('Add budget',form([['scope_type','Scope type','global'],['scope_value','Scope value','*'],['monthly_usd','Monthly USD','100'],['warning_percent','Warning %','80'],['hard_stop_percent','Hard stop %','100'],['action','Action','hard_stop']],`create('budgets','Budgets')`))}
async function pageUsersKeys(){const [u,k]=await Promise.all([api('users'),api('keys')]);$('#page').innerHTML=`<div class="toolbar"><button class="btn primary" onclick="newUser()">Add user</button><button class="btn primary" onclick="newKey()">Create API key</button></div><div class="split"><div class="card"><h2>Users</h2>${table(u,[['User','username'],['Role','role'],['Team','team'],['Active','active']])}</div><div class="card"><h2>Virtual API keys</h2>${table(k,[['Name','name'],['Prefix','prefix'],['Role','role'],['Team','team'],['RPM','rpm'],['Budget','monthly_budget_usd',(v)=>'$'+v],['','id',(v)=>`<button class="btn danger" onclick="del('keys/${v}','Users & Keys')">Revoke</button>`]])}</div></div>`}
function newUser(){modal('Add user',form([['username','Username',''],['password','Password (12+ chars)',''],['role','Role','user'],['team','Team','default']],`create('users','Users & Keys')`,true))}
function newKey(){modal('Create API key',form([['name','Name','client'],['role','Role','user'],['team','Team','default'],['rpm','RPM','60'],['tpm','TPM','200000'],['daily_requests','Daily requests','5000'],['monthly_budget_usd','Monthly budget USD','0'],['allowed_tiers','Allowed tiers CSV','fast,standard,strong']],`createKey()`))}
async function createKey(){const d=collect();d.rpm=+d.rpm;d.tpm=+d.tpm;d.daily_requests=+d.daily_requests;d.monthly_budget_usd=+d.monthly_budget_usd;d.allowed_tiers=d.allowed_tiers.split(',').map(x=>x.trim());const r=await api('keys',{method:'POST',body:JSON.stringify(d)});modal('Copy this key now',`<p class="warn">It is shown only once.</p><div class="code">${esc(r.created_key)}</div><br><button class="btn" onclick="navigator.clipboard.writeText('${r.created_key}');toast('Copied')">Copy</button>`)}
async function pagePolicies(){const d=await api('policies');$('#page').innerHTML=`<div class="toolbar"><button class="btn primary" onclick="newPolicy()">Add policy</button></div><div class="card">${table(d,[['Name','name'],['Priority','priority'],['Enabled','enabled'],['Rule','rule',(v)=>`<span class="code">${esc(JSON.stringify(v))}</span>`],['Action','action',(v)=>`<span class="code">${esc(JSON.stringify(v))}</span>`],['','id',(v)=>`<button class="btn danger" onclick="del('policies/${v}','Policies')">Delete</button>`]])}</div>`}
function newPolicy(){modal('Add guardrail policy',`<div class="formgrid"><label>Name<input id="f_name" value="protect-production"></label><label>Priority<input id="f_priority" value="100"></label><label class="wide">Rule JSON<textarea id="f_rule">{"roles":["user"],"prompt_contains":["production"]}</textarea></label><label class="wide">Action JSON<textarea id="f_action">{"force_min_tier":"strong"}</textarea></label><div class="wide"><button class="btn primary" onclick="createPolicy()">Create</button></div></div>`)}
async function createPolicy(){await api('policies',{method:'POST',body:JSON.stringify({name:$('#f_name').value,priority:+$('#f_priority').value,enabled:true,rule:JSON.parse($('#f_rule').value),action:JSON.parse($('#f_action').value)})});closeModal();show('Policies')}
async function pageKnowledge(){const d=await api('knowledge');$('#page').innerHTML=`<div class="toolbar"><button class="btn primary" onclick="newKB()">New knowledge base</button><button class="btn" onclick="searchKB()">Test search</button></div><div class="card">${table(d,[['ID','id'],['Name','name'],['Description','description'],['Chunks','chunks'],['Owner','owner'],['Actions','id',(v)=>`<button class="btn" onclick="ingest(${v})">Ingest</button> <button class="btn danger" onclick="del('knowledge/${v}','Knowledge')">Delete</button>`]])}</div>`}
function newKB(){modal('New knowledge base',form([['name','Name','infrastructure'],['description','Description','Runbooks, docs and repositories']],`create('knowledge','Knowledge')`))}
function ingest(id){modal('Ingest document',`<div class="formgrid"><label>Source<input id="f_source" value="manual"></label><label>Title<input id="f_title"></label><label class="wide">Content<textarea id="f_content" style="min-height:260px"></textarea></label><div class="wide"><button class="btn primary" onclick="ingestGo(${id})">Chunk & index</button></div></div>`)}
async function ingestGo(id){const r=await api(`knowledge/${id}/documents`,{method:'POST',body:JSON.stringify({source:$('#f_source').value,title:$('#f_title').value,content:$('#f_content').value})});closeModal();toast(r.chunks+' chunks indexed');show('Knowledge')}
function searchKB(){modal('Search knowledge',`<div class="formgrid"><label>KB IDs CSV<input id="q_ids"></label><label>Query<input id="q_text"></label><div class="wide"><button class="btn primary" onclick="searchGo()">Search</button></div><div class="wide" id="q_results"></div></div>`)}
async function searchGo(){const r=await api('knowledge/search',{method:'POST',body:JSON.stringify({kb_ids:$('#q_ids').value.split(',').map(Number).filter(Boolean),query:$('#q_text').value})});$('#q_results').innerHTML=`<div class="code">${esc(JSON.stringify(r,null,2))}</div>`}
async function pageMemory(){const d=await api('memory');$('#page').innerHTML=`<div class="toolbar"><button class="btn primary" onclick="newMemory()">Add memory</button></div><div class="card">${table(d,[['Scope','scope_type'],['Value','scope_value'],['Key','key'],['Memory','value'],['Updated','updated_at'],['','id',(v)=>`<button class="btn danger" onclick="del('memory/${v}','Memory')">Delete</button>`]])}</div>`}
function newMemory(){modal('Add persistent memory',form([['scope_type','Scope type','project'],['scope_value','Scope value','production-k8s'],['key','Key','namespace'],['value','Value','backend']],`create('memory','Memory')`))}
async function pageAgents(){const d=await api('agents');$('#page').innerHTML=`<div class="toolbar"><button class="btn primary" onclick="newAgent()">New agent</button></div><div class="card">${table(d,[['ID','id'],['Name','name'],['Tier','tier'],['Profile','profile'],['Knowledge','knowledge',(v)=>esc(v.join(','))],['Active','active'],['Actions','id',(v)=>`<button class="btn" onclick="runAgent(${v})">Run</button> <button class="btn danger" onclick="del('agents/${v}','Agents')">Disable</button>`]])}</div>`}
function newAgent(){modal('New agent',`<div class="formgrid"><label>Name<input id="f_name" value="devops-agent"></label><label>Tier<input id="f_tier" value="auto"></label><label>Profile<input id="f_profile" value="coding"></label><label>Knowledge IDs CSV<input id="f_knowledge"></label><label class="wide">System prompt<textarea id="f_system_prompt">You are a careful DevOps specialist. Explain risk before changes.</textarea></label><div class="wide"><button class="btn primary" onclick="createAgent()">Create</button></div></div>`)}
async function createAgent(){await api('agents',{method:'POST',body:JSON.stringify({name:$('#f_name').value,tier:$('#f_tier').value,profile:$('#f_profile').value,knowledge:$('#f_knowledge').value.split(',').map(Number).filter(Boolean),system_prompt:$('#f_system_prompt').value})});closeModal();show('Agents')}
function runAgent(id){modal('Run agent',`<textarea id="agentTask" placeholder="Task"></textarea><br><br><button class="btn primary" onclick="runAgentGo(${id})">Run</button><div id="agentOut" class="section"></div>`)}
async function runAgentGo(id){$('#agentOut').innerHTML='<span class="muted">Running…</span>';const r=await api(`agents/${id}/run`,{method:'POST',body:JSON.stringify({task:$('#agentTask').value})});$('#agentOut').innerHTML=`<div class="code">${esc(JSON.stringify(r,null,2))}</div>`}
async function pageTeams(){const d=await api('teams');$('#page').innerHTML=`<div class="toolbar"><button class="btn primary" onclick="newTeam()">New team</button></div><div class="card">${table(d,[['ID','id'],['Name','name'],['Strategy','strategy'],['Agents','agent_ids',(v)=>esc(v.join(','))],['Synthesis','synthesis_tier'],['Actions','id',(v)=>`<button class="btn" onclick="runTeam(${v})">Run</button> <button class="btn danger" onclick="del('teams/${v}','Teams')">Disable</button>`]])}</div>`}
function newTeam(){modal('New agent team',form([['name','Name','incident-response'],['strategy','Strategy sequential/parallel','parallel'],['agent_ids','Agent IDs CSV','1,2'],['synthesis_tier','Synthesis tier','strong']],`createTeam()`))}
async function createTeam(){const d=collect();d.agent_ids=d.agent_ids.split(',').map(Number).filter(Boolean);await api('teams',{method:'POST',body:JSON.stringify(d)});closeModal();show('Teams')}
function runTeam(id){modal('Run team',`<textarea id="teamTask" placeholder="Task"></textarea><br><br><button class="btn primary" onclick="runTeamGo(${id})">Run</button><div id="teamOut" class="section"></div>`)}
async function runTeamGo(id){$('#teamOut').innerHTML='<span class="muted">Running…</span>';const r=await api(`teams/${id}/run`,{method:'POST',body:JSON.stringify({task:$('#teamTask').value})});$('#teamOut').innerHTML=`<div class="code">${esc(JSON.stringify(r,null,2))}</div>`}
async function pagePlugins(){const d=await api('plugins');$('#page').innerHTML=`<div class="toolbar"><button class="btn primary" onclick="newPlugin()">Register plugin/tool</button></div><div class="card">${table(d,[['Name','name'],['Kind','kind'],['Endpoint','endpoint'],['Risk','risk'],['Enabled','enabled'],['Description','description'],['','id',(v)=>`<button class="btn danger" onclick="del('plugins/${v}','Plugins')">Delete</button>`]])}</div><div class="card section"><h2>Safety model</h2><p class="muted">Registry entries are metadata until explicitly enabled and attached to an agent. v0.5.1 does not auto-execute arbitrary remote tools from model output.</p></div>`}
function newPlugin(){modal('Register plugin/tool',form([['name','Name','github-mcp'],['kind','Kind (mcp/http/webhook)','mcp'],['endpoint','Endpoint',''],['risk','Risk','medium'],['description','Description','GitHub tools']],`create('plugins','Plugins')`))}
async function pageAudit(){const d=await api('audit?limit=300');$('#page').innerHTML=`<div class="card">${table(d,[['Time','ts'],['Actor','actor'],['Role','role'],['Action','action'],['Resource','resource'],['Status','status'],['Detail','detail',(v)=>`<span class="code">${esc(JSON.stringify(v))}</span>`]])}</div>`}
async function pageSystem(){const d=await api('system');$('#page').innerHTML=cards([['Version',d.version,'Smart Router'],['Control DB',d.database_ok?'OK':'DOWN',d.control_db],['HA mode',d.ha_mode?'ON':'OFF','stateless sticky mode'],['Auth required',d.require_auth?'YES':'NO','OpenAI-compatible API']])+`<div class="card section"><h2>Runtime</h2><div class="code">${esc(JSON.stringify(d,null,2))}</div></div>`}
function form(fields,onclick,password=false){return `<div class="formgrid">${fields.map(([id,l,v])=>`<label>${l}<input id="f_${id}" ${password&&id==='password'?'type="password"':''} value="${esc(v)}"></label>`).join('')}<div class="wide"><button class="btn primary" onclick="${onclick}">Save</button></div></div>`}
function collect(){const d={};document.querySelectorAll('#modal [id^="f_"]').forEach(x=>d[x.id.slice(2)]=x.value);return d}
async function create(path,page){const d=collect();if(d.monthly_usd)d.monthly_usd=+d.monthly_usd;if(d.priority)d.priority=+d.priority;await api(path,{method:'POST',body:JSON.stringify(d)});closeModal();toast('Saved');show(page)}
async function del(path,page){if(!confirm('Continue?'))return;await api(path,{method:'DELETE'});toast('Updated');show(page)}
function modal(t,b){$('#modalTitle').textContent=t;$('#modalBody').innerHTML=b;$('#modal').classList.add('open')}function closeModal(){$('#modal').classList.remove('open')}
if(token)boot().catch(showLogin);else showLogin();
</script></body></html>'''
